/** Total number of unique icons across all packs */
export const TOTAL_ICON_COUNT = 48958;



/** Find which pack a given icon name belongs to */
let _nameToSlug: Map<string, string> | null = null;
export function getPackForIcon(iconName: string): string | null {
  if (!_nameToSlug) {
    _nameToSlug = new Map();
    for (const pack of ICON_PACKS) {
      for (const name of pack.icons) {
        _nameToSlug.set(name, pack.slug);
      }
    }
  }
  return _nameToSlug.get(iconName) ?? null;
}
